package com.yongdrel.scheduler_ttl_service.application.service;
import com.yongdrel.scheduler_ttl_service.adapter.out.persistence.*;import org.junit.jupiter.api.*;import java.time.Instant;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class LeaseServiceTest{@Test void expiredLeaseCanBeAcquired(){LeaseRepository r=mock(LeaseRepository.class);JobLeaseEntity l=new JobLeaseEntity("x");when(r.lock("x")).thenReturn(Optional.of(l));assertTrue(new LeaseService(r).acquire("x",60));}@Test void activeLeaseBlocksDuplicateScheduler(){LeaseRepository r=mock(LeaseRepository.class);JobLeaseEntity l=new JobLeaseEntity("x");l.renew(Instant.now().plusSeconds(60));when(r.lock("x")).thenReturn(Optional.of(l));assertFalse(new LeaseService(r).acquire("x",60));}}
